 const h2=(v[0]*v[0]+v[1]*v[1]+v[2]*v[2])*r2 - Math.pow(p[0]*v[0]+p[1]*v[1]+p[2]*v[2],2);
 const k=-1.5*h2/(r2*r2*r);
 return [p[0]*k,p[1]*k,p[2]*k];
}
