const canvas = document.getElementById('scene');
const loading = document.getElementById('loading');
const loadingText = document.getElementById('loadingText');

loadThree().then((THREE) => {
  loadingText.textContent = '正在生成黑洞…';

  const renderer = new THREE.WebGLRenderer({
    canvas,
    antialias: false,
    alpha: false,
    stencil: false,
    depth: false,
    powerPreference: 'high-performance'
  });
  renderer.setClearColor(0x000000, 1);
  renderer.autoClear = true;

  const starTexture = createStarfieldTexture(THREE);

  const uniforms = {
    uTime: { value: 0 },
    uYaw: { value: 0 },
    uPitch: { value: 0.35 },
    uCamDist: { value: 13.0 },
    uFov: { value: 58.0 },
    uAspect: { value: 1.0 },
    uExposure: { value: 1.15 },
    uStars: { value: starTexture }
  };

  const scene = new THREE.Scene();
  const camera = new THREE.OrthographicCamera(-1, 1, 1, -1, 0, 1);
  const geometry = new THREE.PlaneGeometry(2, 2);
  const material = new THREE.ShaderMaterial({
    vertexShader: VERTEX_SHADER,
    fragmentShader: FRAGMENT_SHADER,
    uniforms,
    depthTest: false,
    depthWrite: false
  });
  const quad = new THREE.Mesh(geometry, material);
  quad.frustumCulled = false;
  scene.add(quad);

  function fitViewport() {
    const w = window.innerWidth;
    const h = window.innerHeight;
    // Keep the ray tracer near 1080p even on very large / HiDPI displays.
    const maxPixels = 1920 * 1080;
    let pr = Math.min(window.devicePixelRatio || 1, 2.0);
    if (w * h * pr * pr > maxPixels) {
      pr = Math.sqrt(maxPixels / (w * h));
    }
    renderer.setPixelRatio(pr);
    renderer.setSize(w, h, false);
    canvas.style.width = '100%';
    canvas.style.height = '100%';
    uniforms.uAspect.value = renderer.domElement.width / renderer.domElement.height;
  }
  window.addEventListener('resize', fitViewport);
  fitViewport();

  /* Interaction: drag orbit + wheel zoom + double-click reset. */
  let yaw = 0.0;
  let pitch = 0.35;
  let camDist = 13.0;
  let dragging = false;
  let lastX = 0, lastY = 0;
  let velYaw = 0, velPitch = 0;

  const clamp = (x, a, b) => Math.max(a, Math.min(b, x));
  const clampPitch = (v) => {
    v = clamp(v, -1.25, 1.25);
    if (Math.abs(v) < 0.06) v = v < 0 ? -0.06 : 0.06;
    return v;
  };

  canvas.addEventListener('pointerdown', (e) => {
    dragging = true;
    velYaw = velPitch = 0;
    lastX = e.clientX;
    lastY = e.clientY;
    canvas.classList.add('dragging');
    try { canvas.setPointerCapture(e.pointerId); } catch (_) {}
  });

  canvas.addEventListener('pointermove', (e) => {
    if (!dragging) return;
    const dx = e.clientX - lastX;
    const dy = e.clientY - lastY;
    lastX = e.clientX;
    lastY = e.clientY;
    yaw += dx * 0.0052;
    pitch = clampPitch(pitch + dy * 0.0052);
    velYaw = dx * 0.0052;
    velPitch = dy * 0.0052;
  });

  const endDrag = () => {
    dragging = false;
    canvas.classList.remove('dragging');
  };
  canvas.addEventListener('pointerup', endDrag);
  canvas.addEventListener('pointercancel', endDrag);
  canvas.addEventListener('lostpointercapture', endDrag);

  canvas.addEventListener('wheel', (e) => {
    e.preventDefault();
    camDist = clamp(camDist * Math.exp(e.deltaY * 0.001), 6.5, 18.0);
  }, { passive: false });

  canvas.addEventListener('dblclick', () => {
    yaw = 0.0;
    pitch = 0.35;
    camDist = 13.0;
    velYaw = velPitch = 0;
  });

  const clock = new THREE.Clock();
  function animate() {
    requestAnimationFrame(animate);

    const dt = Math.min(clock.getDelta(), 0.05);
    uniforms.uTime.value = clock.elapsedTime;

    if (!dragging) {
      // Light inertia.
      if (Math.abs(velYaw) > 0.00003 || Math.abs(velPitch) > 0.00003) {
        yaw += velYaw;
        pitch = clampPitch(pitch + velPitch);
        velYaw *= 0.94;
        velPitch *= 0.94;
      } else {
        velYaw = velPitch = 0;
      }
    }
    uniforms.uYaw.value = yaw;
    uniforms.uPitch.value = pitch;
    uniforms.uCamDist.value = camDist;

    renderer.render(scene, camera);
  }

  animate();
  loading.style.opacity = '0';
  setTimeout(() => loading.remove(), 700);
}).catch((err) => {
  console.error(err);
  loadingText.textContent = 'Three.js 加载失败，请确认网络可访问 CDN 后刷新重试。';
});
</script>
