function importWithTimeout(url, ms = 12000) {
  return Promise.race([
    import(url),
    new Promise((_, reject) => setTimeout(() => reject(new Error('timeout: ' + url)), ms))
  ]);
}

async function loadThree() {
  let lastError = null;
  for (const url of CDN_SOURCES) {
