/* ------------------------------------------------------------------ *
 *  Procedural starfield (equirectangular panorama, generated offline)
 * ------------------------------------------------------------------ */
function createStarfieldTexture(THREE) {
  const W = 2048, H = 1024;
  const canvas = document.createElement('canvas');
  canvas.width = W; canvas.height = H;
  const ctx = canvas.getContext('2d');

  // Deep-space base gradient.
  const bg = ctx.createLinearGradient(0, 0, 0, H);
  bg.addColorStop(0, '#010108');
  bg.addColorStop(0.45, '#02020c');
  bg.addColorStop(1, '#03030f');
  ctx.fillStyle = bg;
  ctx.fillRect(0, 0, W, H);

  // Approximate normal distribution in [-1, 1].
  const randn = () => (Math.random() + Math.random() + Math.random() + Math.random() - 2.0) * 0.55;
  const bandYAt = (x) => H * (0.50 + 0.19 * Math.sin(x / W * Math.PI * 2.0 * 1.35 + 1.1)
                                 + 0.05 * Math.sin(x / W * Math.PI * 2.0 * 3.7 + 0.4));

  // Soft galactic band / nebulae.
  ctx.globalCompositeOperation = 'lighter';
  const nebColors = [
    '38, 52, 105', '26, 18, 58', '88, 42, 82',
    '110, 58, 40', '20, 34, 70', '70, 28, 52'
  ];
  for (let i = 0; i < 42; i++) {
    const x = Math.random() * W;
    const onBand = Math.random() < 0.72;
    const y = onBand ? bandYAt(x) + randn() * H * 0.11 : Math.random() * H;
    const yy = ((y % H) + H) % H;
    const rad = 120 + Math.random() * 330;
    const col = nebColors[(Math.random() * nebColors.length) | 0];
    const g = ctx.createRadialGradient(x, yy, 0, x, yy, rad);
    g.addColorStop(0, `rgba(${col},${0.025 + Math.random() * 0.035})`);
    g.addColorStop(1, `rgba(${col},0)`);
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.arc(x, yy, rad, 0, Math.PI * 2);
    ctx.fill();
  }

  // Bright core of the Milky-Way-like band.
  ctx.filter = 'blur(26px)';
  for (let layer = 0; layer < 3; layer++) {
    ctx.beginPath();
    for (let x = 0; x <= W; x += 12) {
      const t = x / W * Math.PI * 2.0;
      const y = H * (0.5 + 0.19 * Math.sin(t * 1.35 + 1.1) + 0.05 * Math.sin(t * 3.7 + 0.4))
              + layer * 14;
      if (x === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
    }
    ctx.strokeStyle = layer === 2
      ? 'rgba(8, 6, 16, 0.45)'
      : 'rgba(188, 178, 210, 0.055)';
    ctx.lineWidth = 150 - layer * 36;
    ctx.globalAlpha = 1;
    ctx.stroke();
  }
  ctx.filter = 'none';

  // Stars. More stars cluster near the galactic band.
  const palette = [
    { rgb: '255,255,255', w: 0.38 },
    { rgb: '172,196,255', w: 0.24 },
    { rgb: '255,240,210', w: 0.18 },
    { rgb: '255,205,150', w: 0.12 },
    { rgb: '255,130,100', w: 0.08 }
  ];
  const totalW = palette.reduce((s, p) => s + p.w, 0);

  for (let i = 0; i < 2600; i++) {
    const x = Math.random() * W;
    const nearBand = Math.random() < 0.62;
    let y = nearBand ? bandYAt(x) + randn() * H * 0.10 : Math.random() * H;
    y = ((y % H) + H) % H;

    let r = Math.random() * totalW, idx = 0;
    while (r > palette[idx].w) { r -= palette[idx].w; idx++; }
    const star = palette[idx];

    const size = Math.pow(Math.random(), 3.2) * 1.65 + 0.22;
    const alpha = Math.pow(Math.random(), 2.4) * 0.85 + 0.10;
    ctx.globalAlpha = alpha;
    ctx.fillStyle = `rgb(${star.rgb})`;

    ctx.beginPath();
    ctx.arc(x, y, size, 0, Math.PI * 2);
    ctx.fill();

    if (size > 1.15) {
      const glow = ctx.createRadialGradient(x, y, 0, x, y, size * 5.5);
      glow.addColorStop(0, `rgba(${star.rgb},${alpha * 0.55})`);
      glow.addColorStop(1, `rgba(${star.rgb},0)`);
      ctx.fillStyle = glow;
      ctx.beginPath();
      ctx.arc(x, y, size * 5.5, 0, Math.PI * 2);
      ctx.fill();
    }
  }
  ctx.globalAlpha = 1;

  // A few tiny distant galaxies.
  for (let i = 0; i < 7; i++) {
    const x = Math.random() * W;
    const y = Math.random() * H;
    const rx = 4 + Math.random() * 9;
    const ry = rx * (0.22 + Math.random() * 0.5);
    const ang = Math.random() * Math.PI;
    ctx.save();
    ctx.translate(x, y);
    ctx.rotate(ang);
    const g = ctx.createRadialGradient(0, 0, 0, 0, 0, rx);
    g.addColorStop(0, 'rgba(210,214,230,0.5)');
    g.addColorStop(0.25, 'rgba(150,150,175,0.16)');
    g.addColorStop(1, 'rgba(150,150,175,0)');
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.ellipse(0, 0, rx, ry, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();
  }

  const tex = new THREE.CanvasTexture(canvas);
  tex.wrapS = THREE.RepeatWrapping;
  tex.wrapT = THREE.ClampToEdgeWrapping;
  tex.magFilter = THREE.LinearFilter;
  tex.minFilter = THREE.LinearMipMapLinearFilter;
  tex.generateMipmaps = true;
  tex.colorSpace = THREE.NoColorSpace;   // decoded manually in the shader
  tex.flipY = false;
  tex.needsUpdate = true;
  return tex;
}

/* ------------------------------------------------------------------ *
 *  Shaders: Schwarzschild null-geodesic ray tracer
 * ------------------------------------------------------------------ */
const VERTEX_SHADER = `
  varying vec2 vUv;
  void main() {
    vUv = uv;
    gl_Position = vec4(position.xy, 0.0, 1.0);
  }
`;

const FRAGMENT_SHADER = `
  varying vec2 vUv;

  uniform float uTime;
  uniform float uYaw;
  uniform float uPitch;
  uniform float uCamDist;
  uniform float uFov;
  uniform float uAspect;
  uniform float uExposure;
  uniform sampler2D uStars;

  const float PI = 3.141592653589793;
  const int MAX_STEPS = 430;

  // Units: Schwarzschild radius Rs = 1.
  const float HORIZON = 1.0;     // event horizon
  const float DISK_IN = 2.9;     // accretion disk inner edge (near ISCO = 3 Rs)
  const float DISK_OUT = 8.0;    // accretion disk outer edge
  const float FAR = 40.0;        // integration cutoff

  /* Exact Schwarzschild null-geodesic acceleration in Cartesian
     Boyer-Lindquist-like coordinates.  For Rs = 1 the photon sphere
     lies at r = 1.5. */
  vec3 accel(vec3 p, vec3 v) {
    float r2 = dot(p, p);
    float r = sqrt(r2);
    float h2 = dot(v, v) * r2 - dot(p, v) * dot(p, v);
    return -1.5 * h2 * p / (r2 * r2 * r);
  }

  float hash21(vec2 p) {
    return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123);
  }

  float vnoise(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);
    f = f * f * (3.0 - 2.0 * f);
    float a = hash21(i);
    float b = hash21(i + vec2(1.0, 0.0));
    float c = hash21(i + vec2(0.0, 1.0));
    float d = hash21(i + vec2(1.0, 1.0));
    return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
  }

  float fbm(vec2 p) {
    float v = 0.0;
    float amp = 0.5;
    for (int i = 0; i < 5; i++) {
      v += amp * vnoise(p);
      p = p * 2.03 + vec2(7.31, 3.17);
      amp *= 0.5;
    }
    return v;
  }

  vec3 diskTemperature(float t) {
    vec3 c1 = vec3(0.72, 0.83, 1.00); // hot inner edge
    vec3 c2 = vec3(1.00, 0.88, 0.60);
    vec3 c3 = vec3(1.00, 0.50, 0.18);
    vec3 c4 = vec3(0.55, 0.12, 0.04); // cool outer edge
    if (t < 0.35) return mix(c1, c2, smoothstep(0.0, 0.35, t));
    if (t < 0.70) return mix(c2, c3, smoothstep(0.35, 0.70, t));
    return mix(c3, c4, smoothstep(0.70, 1.0, t));
  }

  float diskProfile(float r) {
    float t = clamp((r - DISK_IN) / (DISK_OUT - DISK_IN), 0.0, 1.0);
    float inner = smoothstep(DISK_IN - 0.20, DISK_IN + 0.15, r);
    float outer = 1.0 - smoothstep(DISK_OUT - 2.2, DISK_OUT, r);
    float falloff = mix(1.0, 0.20, t);
    return inner * outer * falloff;
  }

  vec3 diskShade(vec3 hit, vec3 vHit) {
    float r = length(hit.xz);
    float phi = atan(hit.z, hit.x);

    // Differential rotation of the turbulent texture.
    float shear = uTime * 0.30 * pow(DISK_IN / max(r, 0.5), 1.5);
    float ang = phi + shear;

    float n1 = fbm(vec2(ang * 4.0, log(r) * 2.6));
    float n2 = fbm(vec2(ang * 14.0 + n1 * 2.5, log(r) * 7.0));
    float bands = 0.5 + 0.5 * sin(ang * 18.0 + n1 * 10.0 + log(r) * 34.0);
    float patches = 0.40 + 0.85 * n2;
    float textureFactor = clamp(bands * patches * 1.25, 0.30, 1.45);

    float t = clamp((r - DISK_IN) / (DISK_OUT - DISK_IN), 0.0, 1.0);
    vec3 color = diskTemperature(t) * diskProfile(r) * textureFactor;

    // Circular orbital motion (counter-clockwise seen from +Y).
    vec3 ePhi = normalize(vec3(-hit.z, 0.0, hit.x));
    float beta = sqrt(0.5 / max(r - 1.0, 0.15));
    beta = min(beta, 0.96);

    // vHit points from the camera toward the disk; the light actually
    // travels the opposite way, hence the (1 + beta*q) denominator.
    float q = dot(normalize(vHit), ePhi);
    float doppler = sqrt(max(1.0 - beta * beta, 0.0)) / (1.0 + beta * q);
    float gravitational = sqrt(max(1.0 - 1.0 / r, 0.0));
    float g = doppler * gravitational;
    float beaming = pow(max(g, 0.0), 3.0);

    // Relativistic beaming also shifts the apparent temperature.
    vec3 tint = vec3(1.0);
    if (g > 1.0) {
      tint = mix(vec3(1.0), vec3(0.82, 0.89, 1.0), min((g - 1.0) * 2.0, 0.6));
    } else {
      tint = mix(vec3(1.0), vec3(1.0, 0.60, 0.35), min((1.0 - g) * 1.5, 0.55));
    }

    // Slightly brighter when the disk is seen edge-on (larger column depth).
    vec3 nHit = normalize(vHit);
    float limb = 1.0 + 1.35 * (1.0 - abs(nHit.y));

    return color * beaming * tint * limb;
  }

  vec2 dirToUv(vec3 d) {
    float u = atan(d.z, d.x) / (2.0 * PI) + 0.5;
    float v = 0.5 - asin(clamp(d.y, -1.0, 1.0)) / PI;
    return vec2(u, v);
  }

  vec3 sampleStars(vec3 d) {
    vec3 s = texture2D(uStars, dirToUv(d)).rgb;
    return pow(s, vec3(2.2)) * 1.25;
  }

  vec3 acesTonemap(vec3 x) {
    return clamp((x * (2.51 * x + 0.03)) / (x * (2.43 * x + 0.59) + 0.14), 0.0, 1.0);
  }

  void main() {
    vec2 ndc = (vUv - 0.5) * 2.0;
    ndc.x *= uAspect;
    float tanF = tan(radians(uFov) * 0.5);

    // Camera orbits the black hole; the disk lies in the XZ plane.
    float clat = cos(uPitch);
    vec3 camPos = vec3(sin(uYaw) * clat, sin(uPitch), cos(uYaw) * clat) * uCamDist;
    vec3 forward = normalize(-camPos);
    vec3 right = normalize(cross(forward, vec3(0.0, 1.0, 0.0)));
    vec3 up = cross(right, forward);
    vec3 rd = normalize(forward + ndc.x * tanF * right + ndc.y * tanF * up);

    vec3 p = camPos;
    vec3 v = rd;

    float minR = length(p);
    vec3 glow = vec3(0.0);

    bool captured = false;
    bool escaped = false;
    bool diskHit = false;
    vec4 diskColor = vec4(0.0);

    float yPrev = p.y;

    for (int i = 0; i < MAX_STEPS; i++) {
      float r = length(p);
      float dt = 0.024 + 0.086 * clamp((r - 1.0) / 5.0, 0.0, 1.0);

      vec3 pPrev = p;
      vec3 vPrev = v;
      yPrev = p.y;

      // Leapfrog (kick-drift-kick).
      vec3 a = accel(p, v);
      v += 0.5 * a * dt;
      p += v * dt;
      a = accel(p, v);
      v += 0.5 * a * dt;

      float rn = length(p);
      minR = min(minR, rn);

      if (rn < HORIZON) {
        captured = true;
        break;
      }

      // Thin-disk crossing test.
      if (yPrev * p.y < 0.0) {
        float f = yPrev / (yPrev - p.y);
        vec3 hit = mix(pPrev, p, f);
        float diskR = length(hit.xz);
        if (diskR >= DISK_IN && diskR <= DISK_OUT) {
          vec3 vHit = mix(vPrev, v, f);
          diskColor = vec4(diskShade(hit, vHit), 1.0);
          diskHit = true;
          break;
        }
      }

      // Soft coronal glow above/below the accretion disk.
      float cylR = length(p.xz);
      if (cylR > DISK_IN * 0.85 && cylR < DISK_OUT * 1.2) {
        float tGlow = clamp((cylR - DISK_IN) / (DISK_OUT - DISK_IN), 0.0, 1.0);
        float density = exp(-abs(p.y) / (0.09 + 0.05 * cylR));
        vec3 emission = diskTemperature(tGlow) * diskProfile(cylR) * density * dt * 1.9;
        glow = min(glow + emission, vec3(0.42));
      }

      if (rn > FAR) {
        escaped = true;
        break;
      }
    }

    vec3 color;
    if (diskHit) {
      color = diskColor.rgb;
    } else {
      // Lensed starfield. If the integrator ran out of steps while the
      // ray was already heading away from the hole, fade it in anyway;
      // deep near-horizon stragglers stay black.
      vec3 bg = sampleStars(normalize(v));
      float visibility = 1.0;
      if (!escaped) {
        float rEnd = length(p);
        visibility = smoothstep(2.0, 9.0, rEnd);
      }
      color = bg * visibility + glow * 0.85;
      if (captured) color = glow * 0.85;
    }

    color *= uExposure;
    color = acesTonemap(color);
    color = pow(color, vec3(1.0 / 2.2));

    // Gentle vignette.
    vec2 q = vUv - 0.5;
    color *= 1.0 - 0.28 * dot(q, q);

    gl_FragColor = vec4(color, 1.0);
  }
`;

/* ------------------------------------------------------------------ *
 *  Bootstrap
 * ------------------------------------------------------------------ */
const canvas = document.getElementById('scene');
const loading = document.getElementById('loading');
const loadingText = document.getElementById('loadingText');

loadThree().then((THREE) => {
  loadingText.textContent = '正在生成黑洞…';

  const renderer = new THREE.WebGLRenderer({
    canvas,
    antialias: false,
    alpha: false,
    stencil: false,
    depth: false,
    powerPreference: 'high-performance'
  });
  renderer.setClearColor(0x000000, 1);
  renderer.autoClear = true;

  const starTexture = createStarfieldTexture(THREE);

  const uniforms = {
    uTime: { value: 0 },
    uYaw: { value: 0 },
    uPitch: { value: 0.35 },
    uCamDist: { value: 13.0 },
    uFov: { value: 58.0 },
    uAspect: { value: 1.0 },
    uExposure: { value: 1.15 },
    uStars: { value: starTexture }
  };

  const scene = new THREE.Scene();
  const camera = new THREE.OrthographicCamera(-1, 1, 1, -1, 0, 1);
  const geometry = new THREE.PlaneGeometry(2, 2);
  const material = new THREE.ShaderMaterial({
    vertexShader: VERTEX_SHADER,
    fragmentShader: FRAGMENT_SHADER,
    uniforms,
    depthTest: false,
    depthWrite: false
  });
  const quad = new THREE.Mesh(geometry, material);
  quad.frustumCulled = false;
  scene.add(quad);

  function fitViewport() {
    const w = window.innerWidth;
    const h = window.innerHeight;
    // Keep the ray tracer near 1080p even on very large / HiDPI displays.
    const maxPixels = 1920 * 1080;
    let pr = Math.min(window.devicePixelRatio || 1, 2.0);
    if (w * h * pr * pr > maxPixels) {
      pr = Math.sqrt(maxPixels / (w * h));
    }
    renderer.setPixelRatio(pr);
    renderer.setSize(w, h, false);
    canvas.style.width = '100%';
    canvas.style.height = '100%';
    uniforms.uAspect.value = renderer.domElement.width / renderer.domElement.height;
  }
