  v = clamp(v, -1.25, 1.25);
  if (Math.abs(v) < 0.06) v = v < 0 ? -0.06 : 0.06;
  return v;
}

function bindInteraction(canvasEl) {
  canvasEl.addEventListener('pointerdown', (e) => {
    view.dragging = true;
    view.velYaw = view.velPitch = 0;
    view.lastX = e.clientX;
    view.lastY = e.clientY;
