  yaw: 0.0,
  pitch: 0.35,
  camDist: 13.0,
  dragging: false,
  lastX: 0,
  lastY: 0,
  velYaw: 0,
  velPitch: 0
};

const clamp = (x, a, b) => Math.max(a, Math.min(b, x));
function clampPitch(v) {
  v = clamp(v, -1.25, 1.25);
  if (Math.abs(v) < 0.06) v = v < 0 ? -0.06 : 0.06;
  return v;
}

function bindInteraction(canvasEl) {
  canvasEl.addEventListener('pointerdown', (e) => {
    view.dragging = true;
    view.velYaw = view.velPitch = 0;
    view.lastX = e.clientX;
    view.lastY = e.clientY;
    canvasEl.classList.add('dragging');
    try { canvasEl.setPointerCapture(e.pointerId); } catch (_) {}
  });

  canvasEl.addEventListener('pointermove', (e) => {
    if (!view.dragging) return;
    const dx = e.clientX - view.lastX;
    const dy = e.clientY - view.lastY;
    view.lastX = e.clientX;
    view.lastY = e.clientY;
    view.yaw += dx * 0.0052;
    view.pitch = clampPitch(view.pitch + dy * 0.0052);
    view.velYaw = dx * 0.0052;
    view.velPitch = dy * 0.0052;
  });

  const endDrag = () => {
    view.dragging = false;
    canvasEl.classList.remove('dragging');
  };
  canvasEl.addEventListener('pointerup', endDrag);
  canvasEl.addEventListener('pointercancel', endDrag);
  canvasEl.addEventListener('lostpointercapture', endDrag);

  canvasEl.addEventListener('wheel', (e) => {
    e.preventDefault();
    view.camDist = clamp(view.camDist * Math.exp(e.deltaY * 0.001), 6.5, 18.0);
  }, { passive: false });

  canvasEl.addEventListener('dblclick', () => {
    view.yaw = 0.0;
    view.pitch = 0.35;
    view.camDist = 13.0;
    view.velYaw = view.velPitch = 0;
  });
}

function stepView() {
  if (view.dragging) return;
  if (Math.abs(view.velYaw) > 0.00003 || Math.abs(view.velPitch) > 0.00003) {
    view.yaw += view.velYaw;
    view.pitch = clampPitch(view.pitch + view.velPitch);
    view.velYaw *= 0.94;
    view.velPitch *= 0.94;
  } else {
    view.velYaw = view.velPitch = 0;
  }
}

function hideLoading() {
  loading.style.opacity = '0';
  setTimeout(() => loading.remove(), 650);
}

function showFatal(message) {
  loading.style.opacity = '1';
  loadingText.textContent = message;
}

/* ------------------------------------------------------------------ *
 *  Three.js path (primary)
 * ------------------------------------------------------------------ */
function startThree(THREE) {
