{"command": "$html = Get-Content -Raw blackhole.html
$m = [regex]::Match($html, '(?s)<script type="module">(.*?)</script>')
$code = $m.Groups[1].Value
$old = @'
loadThree()
  .then(startThree)
  .catch((err) => {
    console.warn('Three.js CDN unavailable, using the built-in WebGL fallback.', err);
    try {
      startRawWebGL();
    } catch (fallbackErr) {
      console.error(fallbackErr);
      showFatal('WebGL 初始化失败：' + fallbackErr.message);
    }
  });
'@
$new = 'startRawWebGL();'
if(-not $code.Contains($old)){ throw 'boot block not found' }
$code = $code.Replace($old, $new)

$mock = @'
const noop = () => {};
function makeGradient(){ return { addColorStop: noop }; }
const ctx2d = new Proxy({}, {
  get(target, prop) {
    if (prop === 'createLinearGradient' || prop === 'createRadialGradient') return () => makeGradient();
    if (prop in target) return target[prop];
    return noop;
  },
  set(target, prop, value) { target[prop] = value; return true; }
});
const canvasMock = {
  width: 300, height: 150, style: {},
  classList: { add: noop, remove: noop },
  addEventListener: noop,
  setPointerCapture: noop,
  getContext(type) {
    if (type === '2d') return ctx2d;
    return gl;
  }
};
const gl = new Proxy({}, {
  get(target, prop) {
    if (prop in target) return target[prop];
    if (typeof prop === 'string' && /^[A-Z0-9_]+$/.test(prop)) return prop.length; // constants
    if (prop === 'createShader') return () => ({});
    if (prop === 'createProgram' || prop === 'createBuffer' || prop === 'createTexture') return () => ({});
    if (prop === 'getShaderParameter') return () => true;
    if (prop === 'getProgramParameter') return () => true;
    if (prop === 'getUniformLocation') return () => ({});
    if (prop === 'getAttribLocation') return () => 0;
    if (prop === 'getShaderInfoLog' || prop === 'getProgramInfoLog') return () => '';
    return noop;
  },
  set(target, prop, value) { target[prop] = value; return true; }
});
const loadingMock = {
  style: {}, textContent: '',
  remove: noop
};
globalThis.document = {
  getElementById(id) { return id === 'scene' ? canvasMock : loadingMock; },
  createElement(tag) { return { width:0, height:0, style:{}, getContext(type){ return type==='2d' ? ctx2d : gl; } }; }
};
globalThis.window = {
  innerWidth: 1280, innerHeight: 720,
  devicePixelRatio: 1,
  addEventListener: noop
};
globalThis.performance = { now: () => 0 };
globalThis.requestAnimationFrame = noop;
globalThis.console = console;
'@

$test = $mock + "`n" + $code + "`nconsole.log('RAW_TEST_OK');`n"
Set-Content -Path raw_test.mjs -Value $test -Encoding utf8
node raw_test.mjs
$LASTEXITCODE"}

