{"command": "$html = Get-Content -Raw blackhole.html
$m = [regex]::Match($html, '(?s)<script type="module">(.*?)</script>')
$code = $m.Groups[1].Value
$old = @'
loadThree()
  .then(startThree)
  .catch((err) => {
    console.warn('Three.js CDN unavailable, using the built-in WebGL fallback.', err);
    try {
      startRawWebGL();
    } catch (fallbackErr) {
      console.error(fallbackErr);
      showFatal('WebGL 初始化失败：' + fallbackErr.message);
    }
  });
'@
$code = $code.Replace($old, 'startRawWebGL();')
$mock = @'
const noop = () => {};
function makeGradient(){ return { addColorStop: noop }; }
const ctx2d = new Proxy({}, { get(t,p){ if(p==='createLinearGradient'||p==='createRadialGradient') return ()=>makeGradient(); if(p in t) return t[p]; return noop; }, set(t,p,v){ t[p]=v; return true; } });
const gl = new Proxy({}, { get(t,p){ if(p in t) return t[p]; if(typeof p==='string' && /^[A-Z0-9_]+$/.test(p)) return 1; if(p==='createShader'||p==='createProgram'||p==='createBuffer'||p==='createTexture') return ()=>({}); if(p==='getShaderParameter'||p==='getProgramParameter') return ()=>true; if(p==='getUniformLocation'||p==='getAttribLocation') return ()=>0; if(p==='getShaderInfoLog'||p==='getProgramInfoLog') return ()=>''; return noop; }, set(t,p,v){ t[p]=v; return true; } });
const canvasMock = { width:300, height:150, style:{}, classList:{add:noop,remove:noop}, addEventListener:noop, setPointerCapture:noop, getContext(type){ return type==='2d' ? ctx2d : gl; } };
const loadingMock = { style:{}, textContent:'', remove:noop };
globalThis.document = { getElementById(id){ return id==='scene' ? canvasMock : loadingMock; }, createElement(){ return { width:0,height:0,style:{},getContext(type){ return type==='2d'?ctx2d:gl; } }; } };
globalThis.window = { innerWidth:1280, innerHeight:720, devicePixelRatio:1, addEventListener:noop };
globalThis.performance = { now:()=>0 };
globalThis.requestAnimationFrame = noop;
globalThis.console = console;
'@
$test = $mock + "`n" + $code + "`nconsole.log('RAW_TEST_OK');`n"
Set-Content -Path raw_test2.mjs -Value $test -Encoding utf8
node raw_test2.mjs
$code2=$LASTEXITCODE
Remove-Item raw_test2.mjs
if($code2 -eq 0){'raw mock OK'} else {'raw mock FAIL'}"}

